function inlineFileId(text) {
  let hash = 0;
  const raw = String(text || '');
  for (let i = 0; i < raw.length; i += 1) {
    hash = (Math.imul(31, hash) + raw.charCodeAt(i)) | 0;
  }
  return `inline-${(hash >>> 0).toString(16)}`;
}

